-- « Impression légale » (LecteurImpressionLegale, EcrivainImpressionLegale), lot 10 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 2 000 7xx, roles 2026IL207xx (instances CX sans code affaire), audiences de juin 1990 : hors des fenetres des autres ecrans
-- d'audience ; la recherche par leur date les choisit (PROC_IMPLEG.recherches). Ce qui est retenu ou ecarte : PROC_IMPLEG.attendu.
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TYPE_INSTANCE') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TYPE_INSTANCE varchar(2) NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_TOP_EXPERIAN') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_TOP_EXPERIAN bit NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_DATE_MAJ_INFOG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_DATE_MAJ_INFOG datetime NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ETAT_REDACTION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ETAT_REDACTION varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ETAT_DIFFUSION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ETAT_DIFFUSION varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ETAT_STABILITE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ETAT_STABILITE varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_NUM_REPERTOIRE') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_NUM_REPERTOIRE varchar(10) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_PRONONCER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_PRONONCER int NULL;
IF OBJECT_ID(N'v2.TYPE_DECISION') IS NULL
    CREATE TABLE v2.TYPE_DECISION (R_TYPEDECISI_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_TYPEDECISI_LIBELLE_ECRAN varchar(100) NOT NULL);
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_TYPE_MESURE_LIE') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_TYPE_MESURE_LIE varchar(5) NULL;
IF OBJECT_ID(N'v2.MESURE') IS NULL
    CREATE TABLE v2.MESURE (MSINS_ID_MSINS int NOT NULL PRIMARY KEY, MSINS_ID_INSTN int NOT NULL, MSINS_ID_DCJDC int NOT NULL, MSINS_NUM_MESURE varchar(11) NULL);
IF COL_LENGTH('v2.MESURE', 'MSINS_DATE_OUVERTURE') IS NULL ALTER TABLE v2.MESURE ADD MSINS_DATE_OUVERTURE datetime NULL;

-- Les types : avec une expertise liee (EXP) ou sans. Le compteur JMEXP de l'annee 1990 (les decisions sont de 1990), s'il manque.
EXEC sp_executesql N'
INSERT INTO v2.TYPE_DECISION (R_TYPEDECISI_VALEUR, R_TYPEDECISI_LIBELLE_ECRAN, R_TYPEDECISI_TYPE_MESURE_LIE) VALUES
    (''ILEXP20'', ''Désignation d''''expert du banc'', ''EXP''), (''ILSANS20'', ''Jugement du banc lot 10'', NULL);
IF NOT EXISTS (SELECT 1 FROM num.Compteur WHERE Type = ''JMEXP'')
    INSERT INTO num.Compteur (Type, Annee, Structure, CodageAnnee, Lettre, TailleChrono, Debut) VALUES (''JMEXP'', 1990, ''ALC'', 4, ''X'', 5, 1);';

