                                    DCJDC_ETAT_DIFFUSION, DCJDC_ETAT_STABILITE, DCJDC_NUM_REPERTOIRE, DCJDC_ID_APPAF_PRONONCER)
VALUES (2000706, 2000706, 1, DATEADD(day, -1, @aujourdhui), DATEADD(day, -1, @aujourdhui), ''ILSANS20'', ''3'', ''3'', ''2'', ''9016400001'', 2000706);',
